 16	// UtilizationProbe queries Rapid-MLX status endpoints and normalizes them into
 17	// the shared endpoint utilization shape.
 18	type UtilizationProbe struct {
 19		baseURL string
 20		client  *http.Client
 21		cache   utilization.Cache
 22	}
 23	
 24	// NewUtilizationProbe creates a probe for an OpenAI-compatible Rapid-MLX base
 25	// URL.
 26	func NewUtilizationProbe(baseURL string, client *http.Client) *UtilizationProbe {
 27		if client == nil {
 28			client = http.DefaultClient
 29		}
 30		return &UtilizationProbe{
 31			baseURL: baseURL,
 32			client:  client,
 33		}
 34	}
 35	
 36	// Probe fetches /v1/status from the server root and returns a normalized
 37	// sample. Failures return stale or unknown utilization instead of surfacing
 38	// endpoint unavailability.
 39	func (p *UtilizationProbe) Probe(ctx context.Context) utilization.EndpointUtilization {
 40		snapshot, ok := p.probeStatus(ctx)
 41		if !ok {
 42			if stale, ok := p.cache.Stale(); ok {
 43				return stale
 44			}
 45			return utilization.Unknown(utilization.SourceRapidMLXStatus)
 46		}
 47	
 48		return p.cache.Remember(snapshot.normalize())
 49	}
 50	
 51	func (p *UtilizationProbe) probeStatus(ctx context.Context) (rapidMLXStatusSnapshot, bool) {
 52		body, err := p.get(ctx, utilization.ServerRoot(p.baseURL)+"/status")
 53		if err != nil {
 54			return rapidMLXStatusSnapshot{}, false
 55		}
 56	
 57		snapshot, err := parseRapidMLXStatus(body)
 58		if err != nil {
 59			return rapidMLXStatusSnapshot{}, false
 60		}
 61		return snapshot, true
 62	}
 63	
 64	func parseRapidMLXStatus(body string) (rapidMLXStatusSnapshot, error) {
 65		var raw any
 66		dec := json.NewDecoder(strings.NewReader(body))
 67		dec.UseNumber()
 68		if err := dec.Decode(&raw); err != nil {
 69			return rapidMLXStatusSnapshot{}, err
 70		}
 71	
 72		payload, ok := raw.(map[string]any)
 73		if !ok {
 74			return rapidMLXStatusSnapshot{}, errors.New("rapid-mlx status payload was not an object")
 75		}
 76	
 77		snapshot := rapidMLXStatusSnapshot{
 78			Raw: payload,
 79		}
 80		snapshot.NumRunning = firstInt(payload, "num_running", "running", "requests_running")
 81		snapshot.NumWaiting = firstInt(payload, "num_waiting", "waiting", "requests_waiting")
 82		snapshot.TotalPromptTokens = firstInt(payload, "total_prompt_tokens", "prompt_tokens", "prompt_tokens_total")
 83		snapshot.TotalCompletionTokens = firstInt(payload, "total_completion_tokens", "completion_tokens", "generated_tokens_total")
 84		snapshot.CacheUsage = firstFloat(payload, "cache_usage", "cache_pressure", "cache_usage_ratio")
 85		snapshot.CacheHitType = firstString(payload, "cache_hit_type", "cache_hit")
 86		snapshot.CachedTokens = firstIntPtr(payload, "cached_tokens", "cache_tokens")
 87		snapshot.GeneratedTokens = firstIntPtr(payload, "generated_tokens")
 88		snapshot.MetalActiveMemoryBytes = firstInt64(payload, "metal_active_memory_bytes", "metal_active_bytes", "active_memory_bytes")
 89		snapshot.MetalPeakMemoryBytes = firstInt64(payload, "metal_peak_memory_bytes", "metal_peak_bytes", "peak_memory_bytes")
 90		snapshot.MetalCacheMemoryBytes = firstInt64(payload, "metal_cache_memory_bytes", "metal_cache_bytes", "cache_memory_bytes")
 91	
 92		if metal, ok := firstMap(payload, "metal", "metal_memory", "metal_stats"); ok {
 93			if snapshot.MetalActiveMemoryBytes == nil {
 94				snapshot.MetalActiveMemoryBytes = firstInt64(metal, "active_bytes", "active_memory_bytes")
 95			}
 96			if snapshot.MetalPeakMemoryBytes == nil {
 97				snapshot.MetalPeakMemoryBytes = firstInt64(metal, "peak_bytes", "peak_memory_bytes")
 98			}
 99			if snapshot.MetalCacheMemoryBytes == nil {
100				snapshot.MetalCacheMemoryBytes = firstInt64(metal, "cache_bytes", "cache_memory_bytes")
101			}
102		}
103	
104		if cache, ok := firstMap(payload, "cache", "cache_stats", "cache_state"); ok {
105			if snapshot.CacheUsage == nil {
106				snapshot.CacheUsage = firstFloat(cache, "usage", "pressure", "ratio")
107			}
108			if snapshot.CacheHitType == nil {
109				snapshot.CacheHitType = firstString(cache, "hit_type", "cache_hit_type")
110			}
111			if snapshot.CachedTokens == nil {
112				snapshot.CachedTokens = firstIntPtr(cache, "cached_tokens", "cache_tokens")
113			}
114			if snapshot.GeneratedTokens == nil {
115				snapshot.GeneratedTokens = firstIntPtr(cache, "generated_tokens")
116			}
117		}
118	
119		if active, ok := firstSlice(payload, "active_requests", "requests", "active"); ok {
120			snapshot.ActiveRequests = make([]rapidMLXRequestSnapshot, 0, len(active))
121			for _, entry := range active {
122				req, ok := entry.(map[string]any)
123				if !ok {
124					continue
125				}
126				item := rapidMLXRequestSnapshot{
127					Phase:           firstString(req, "phase", "state"),
128					CacheHitType:    firstString(req, "cache_hit_type", "cache_hit"),
129					CachedTokens:    firstIntPtr(req, "cached_tokens", "cache_tokens"),
130					GeneratedTokens: firstIntPtr(req, "generated_tokens"),
131					TTFTSeconds:     firstFloat(req, "ttft_s", "ttft_seconds"),
132					TokensPerSecond: firstFloat(req, "tokens_per_second", "tokens_per_sec"),
133				}
134				snapshot.ActiveRequests = append(snapshot.ActiveRequests, item)
135			}
136			if len(snapshot.ActiveRequests) > 0 {
137				first := snapshot.ActiveRequests[0]
138				snapshot.ActiveRequestPhase = first.Phase
139				if snapshot.CacheHitType == nil {
140					snapshot.CacheHitType = first.CacheHitType
141				}
142				if snapshot.CachedTokens == nil {
143					snapshot.CachedTokens = first.CachedTokens
144				}
145				if snapshot.GeneratedTokens == nil {
146					snapshot.GeneratedTokens = first.GeneratedTokens
147				}
148				if snapshot.TTFTSeconds == nil {
149					snapshot.TTFTSeconds = first.TTFTSeconds
150				}
151				if snapshot.TokensPerSecond == nil {
152					snapshot.TokensPerSecond = first.TokensPerSecond
153				}
154			}
155		}
156	
157		if snapshot.CacheUsage == nil {
158			switch {
159			case snapshot.MetalActiveMemoryBytes != nil && snapshot.MetalPeakMemoryBytes != nil && *snapshot.MetalPeakMemoryBytes > 0:
160				usage := float64(*snapshot.MetalActiveMemoryBytes) / float64(*snapshot.MetalPeakMemoryBytes)
161				snapshot.CacheUsage = utilization.Float64(usage)
162			case snapshot.MetalCacheMemoryBytes != nil && snapshot.MetalPeakMemoryBytes != nil && *snapshot.MetalPeakMemoryBytes > 0:
163				usage := float64(*snapshot.MetalCacheMemoryBytes) / float64(*snapshot.MetalPeakMemoryBytes)
164				snapshot.CacheUsage = utilization.Float64(usage)
165			}
166		}
167	
168		if snapshot.NumRunning < 0 || snapshot.NumWaiting < 0 {
169			return rapidMLXStatusSnapshot{}, fmt.Errorf("invalid negative running/waiting counts")
170		}
171	
172		return snapshot, nil
173	}
